//go:build ignore

// Generates go_vectors.txt with Go's crypto/ed25519:
//
//	go run gen_go_vectors.go > go_vectors.txt
//
// "sign seed pub msg sig" lines check key derivation and signing; "verify pub msg sig 0|1"
// lines record Go's verdict on valid and altered inputs (a flipped bit in R, S, the key or
// the message, S + L, a key that is not a point, the identity as key, the top bit of R).
package main

import (
	"crypto/ed25519"
	"encoding/hex"
	"fmt"
	"math/big"
	"math/rand"
)

func h(b []byte) string { return hex.EncodeToString(b) }

func main() {
	r := rand.New(rand.NewSource(25519))
	l, _ := new(big.Int).SetString("7237005577332262213973186563042994240857116359379907606001950938285454250989", 10)
	fmt.Println("# generated by gen_go_vectors.go with Go's crypto/ed25519")
	verify := func(pub, msg, sig []byte) {
		ok := 0
		if len(pub) == 32 && ed25519.Verify(ed25519.PublicKey(pub), msg, sig) {
			ok = 1
		}
		fmt.Printf("verify %s %s %s %d\n", h(pub), h(msg), h(sig), ok)
	}
	flip := func(b []byte, i int) []byte {
		c := append([]byte(nil), b...)
		c[i/8] ^= 1 << (i % 8)
		return c
	}
	for n := 0; n < 120; n++ {
		seed := make([]byte, 32)
		r.Read(seed)
		msg := make([]byte, r.Intn(200))
		r.Read(msg)
		key := ed25519.NewKeyFromSeed(seed)
		pub := key.Public().(ed25519.PublicKey)
		sig := ed25519.Sign(key, msg)
		fmt.Printf("sign %s %s %s %s\n", h(seed), h(pub), h(msg), h(sig))
		verify(pub, msg, sig)
		verify(pub, msg, flip(sig, r.Intn(256)))     // R
		verify(pub, msg, flip(sig, 256+r.Intn(256))) // S
		verify(flip(pub, r.Intn(255)), msg, sig)
		verify(pub, append(append([]byte(nil), msg...), 0), sig)
		// S + L (still < 2^256 for most S).
		s := new(big.Int).SetBytes(reverse(sig[32:]))
		s.Add(s, l)
		if s.BitLen() <= 256 {
			sb := s.FillBytes(make([]byte, 32))
			verify(pub, msg, append(append([]byte(nil), sig[:32]...), reverse(sb)...))
		}
		// R with the top bit flipped.
		verify(pub, msg, flip(sig, 255))
	}
	// Keys that are not points and the identity.
	for n := 0; n < 40; n++ {
		pub := make([]byte, 32)
		r.Read(pub)
		msg := []byte{byte(n)}
		sig := make([]byte, 64)
		r.Read(sig)
		sig[63] &= 0x0f
		verify(pub, msg, sig)
	}
	id := make([]byte, 32)
	id[0] = 1
	verify(id, []byte("x"), make([]byte, 64))
}

func reverse(b []byte) []byte {
	c := make([]byte, len(b))
	for i := range b {
		c[i] = b[len(b)-1-i]
	}
	return c
}
